-- Coleção de 10 molduras animadas Eternal. Idempotente por slug; não toca em saldos ou inventários.
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,rarity=EXCLUDED.rarity,preview=EXCLUDED.preview,animation=EXCLUDED.animation,coin_price=EXCLUDED.coin_price,active=true,in_shop=true,effect=EXCLUDED.effect,frame_category=EXCLUDED.frame_category,event_slug=EXCLUDED.event_slug,featured=true;
